  "stuSess.refundContactNote": "如需退款，請聯絡 <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>。",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">有疑問或遇到問題？請聯絡 <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>。</p><p class=\"font-semibold text-emerald-900\">已透過 Stripe 發起退款。</p><p class=\"text-emerald-800 mt-1\">信用卡退款通常會在約 <strong>5–10 個工作天</strong>內到帳（視乎銀行而定）。如超過一般處理時間仍未收到退款，請電郵至 <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>。</p>",
  "stuSess.refundSuccessManualTutor": "<p>此課堂似乎並非透過 Tutlio Stripe 付款（例如銀行轉帳或現金），因此無法在此自動退款。</p><p class=\"mt-2\">如需安排退款，請聯絡你的導師 <strong>{tutor}</strong>，使用預約資料中的電郵或聯絡方式，或直接向導師查詢。</p>",
  "stuSess.refundSuccessManualOrg": "<p>此課堂似乎並非透過 Tutlio Stripe 付款（例如銀行轉帳或現金），因此無法在此自動退款。</p><p class=\"mt-2\">由於你透過機構上課，請聯絡<strong>機構管理員</strong>（可透過導師或機構公布的聯絡方式）。</p>",
