  "enterpriseCheckout.companySummary": "{count} 個導師授權 · 每月 {total}。輸入機構名稱以繼續前往安全付款頁面。",
  "enterpriseCheckout.continueToPayment": "繼續付款",
  "pwa.bannerText": "將 Tutlio 加入主畫面，享受如應用程式般的使用體驗！",
  "pwa.promptTitle": "像應用程式一樣使用 Tutlio",
  "pwa.promptSubtitle": "加入主畫面",
  "pwa.promptDescription": "將 Tutlio 安裝到手機，享受更快捷的應用程式體驗，毋須透過應用程式商店！",
  "pwa.howToInstall": "如何安裝？",
  "pwa.later": "稍後",
  "pwa.dontShowAgain": "不再顯示",
  "pwa.guideTitle": "安裝為手機應用程式",
  "pwa.guideSubtitle": "在手機上像一般應用程式一樣使用 Tutlio",
  "pwa.guideIntro": "你可將 Tutlio 加入手機主畫面，像一般應用程式一樣使用，享受全螢幕及快速開啟的體驗。",
  "pwa.iosStep1": "在 Safari 開啟 Tutlio，按畫面底部的分享按鈕（帶箭嘴的方框）。",
  "pwa.iosStep2": "向下捲動，按「加入主畫面」。",
  "pwa.iosStep3": "按「加入」，Tutlio 圖示便會出現在主畫面。",
