  "orgTutorPolicy.title": "導師內部規則",
  "orgTutorPolicy.intro": "使用平台前，請先閱讀機構的內部規則。",
  "orgTutorPolicy.acceptBtn": "我已明白",
  "orgTutorPolicy.viewBtn": "查看內部規則",
  "orgTutorPolicy.s1Title": "1. 一般條款",
  "orgTutorPolicy.s1Body": "本規則規管你以教師或導師（「導師」）身分使用 Tutlio 平台（「平台」）。你所代表的教育機構、學校或補習中心（「機構」）已邀請你使用平台。平台的技術維護及支援由 MB Tutlio 提供。使用帳戶即表示你同意本規則及私隱政策。",
  "orgTutorPolicy.s2Title": "2. 帳戶管理與時間表",
  "orgTutorPolicy.s2Intro": "平台旨在節省你與學生協調上課時間的工夫。",
  "orgTutorPolicy.s2Link": "專屬連結：你會獲分配個人課堂預約連結，按所教授科目供學生安排課堂。",
  "orgTutorPolicy.s2Calendar": "日曆同步：可預約時段直接取決於 Google Calendar 整合（雙向同步）。你須自行確保日曆顯示的可用時間準確及保持更新。平台不會讓學生預約已標記為忙碌的時段。",
  "orgTutorPolicy.s2Security": "帳戶安全：帳戶只供你個人使用。你須妥善保管登入資料，不得與第三方分享。",
  "orgTutorPolicy.s3Title": "3. 課堂取消與候補名單",
  "orgTutorPolicy.s3Intro": "平台協助充分利用時間表，減少空置時段：",
  "orgTutorPolicy.s3Auto": "學生取消課堂時，平台會自動向候補名單中的其他學生發送通知（短訊／電郵），提供空出的時段。你毋須另作操作。",
  "orgTutorPolicy.s3Rules": "課堂取消規則，包括須提前多久取消及相關後果，均由你的機構設定。",
  "orgTutorPolicy.s4Title": "4. 財務與付款",
  "orgTutorPolicy.s4Intro": "你毋須自行處理發票或向家長收款：",
  "orgTutorPolicy.s4Advance": "學生或家長的所有課堂付款均透過平台預先收取，並直接轉交你的機構。",
  "orgTutorPolicy.s4Confirmed": "只有系統已確認的課堂才可進行，即課堂費用已收取。",
  "orgTutorPolicy.s4Contact": "如需查詢薪酬、發薪時間及其他財務事宜，請直接聯絡機構管理員。MB Tutlio 不會與導師直接進行任何財務交易。",
  "orgTutorPolicy.s5Title": "5. 學生資料保障（GDPR）",
  "orgTutorPolicy.s5Intro": "作為導師，你可存取學生個人資料、內部筆記及學習材料。你承諾：",
  "orgTutorPolicy.s5Use": "只將此資料用於安排及進行課堂。",
  "orgTutorPolicy.s5NoCopy": "不將學生或家長的聯絡資料複製、匯出或散布至平台以外。",
  "orgTutorPolicy.s5Notes": "妥善保管機構內部記錄，例如學生進度筆記。這些資料只供你及機構行政人員查看，不向學生或家長公開。",
  "orgTutorPolicy.s5Termination": "你與機構的工作關係結束後，存取此資料的權限會立即撤銷。",
  "orgTutorPolicy.s6Title": "6. 技術運作與責任限制",
  "orgTutorPolicy.s6Body": "禁止利用平台從事違法活動、在教材中散布惡意連結，或以其他方式干擾系統。MB Tutlio 負責平台運作及技術維護，但不承擔因你的網絡連線、裝置故障或 Google Calendar 設定不正確而造成的中斷責任。",
  "orgTutorPolicy.s7Title": "7. 支援與聯絡",
  "orgTutorPolicy.s7Org": "如有關於課堂時間表、薪酬、學生分配或工作安排的問題，請聯絡機構管理員。",
  "orgTutorPolicy.s7Tech": "如遇平台技術問題，例如日曆無法同步或未收到通知，請通知機構管理員，由他們聯絡 Tutlio 技術支援團隊。",
  "register.orgPolicyConsent": "使用平台即表示你同意",
  "register.orgPolicyLink": "內部政策",
