  "quiz.info.insight.solo.title": "每多一位學生，行政工作便隨之增加",
  "quiz.info.insight.solo.body": "工作量通常不是一次出現的大問題，而是每堂課前後的小動作不斷累積。",
  "quiz.info.insight.solo.point1": "一堂課改期，可能同時涉及日曆更改、訊息及付款調整。",
  "quiz.info.insight.solo.point2": "筆記分散各處，連簡單的學生問題也需要更多時間回答。",
  "quiz.info.insight.solo.point3": "流程相連，學生增加時仍可保留教學時間。",
  "quiz.info.insight.company.title": "營運阻滯會隨補習團隊擴大而累積",
  "quiz.info.insight.company.body": "一個小小的手動步驟，當每位導師、學生及管理員都要重複時，便會成為嚴重障礙。",
  "quiz.info.insight.company.point1": "共用時間表，讓團隊以同一份準確資料處理日常工作。",
  "quiz.info.insight.company.point2": "課堂狀態應直接連接導師薪酬、收費及報告，毋須重複輸入。",
  "quiz.info.insight.company.point3": "角色清晰，每人都可處理自己的工作，而毋須開放整個機構工作空間。",
  "quiz.info.insight.school.title": "學校行政各環節息息相關",
  "quiz.info.insight.school.body": "合約、學生資料、分期付款、家長溝通及會計互相影響，分散的檔案會令流程中斷。",
  "quiz.info.insight.school.point1": "合約狀態應與學生資料一同顯示，毋須另外追蹤。",
  "quiz.info.insight.school.point2": "分期付款時間表須清楚連結至正確的付款人及合約。",
  "quiz.info.insight.school.point3": "財務資料預先整理成適合報告的格式，便更容易使用。",
