  "quiz.offer.testimonial.solo.role4": "物理導師",
  "quiz.offer.testimonial.solo.copy4": "「我可以立即在日曆看到課堂、更改及付款狀態，日常行政工作變得更省時、更清晰。」",
  "quiz.offer.testimonial.company.copy1": "「以前課堂更改、導師評語及工時都透過不同訊息送達。現在行政團隊可以從同一份時間表掌握全貌。」",
