  "quiz.offer.testimonial.company.role4": "財務協調員 · 22 位導師",
  "quiz.offer.testimonial.company.copy4": "「不同課堂類型採用不同導師薪酬規則，以前月底需要大量手動核對。Tutlio 流程讓整個過程從容得多。」",
