  "quiz.offer.testimonial.school.role2": "招生協調員 · 86 位學生",
  "quiz.offer.testimonial.school.copy2": "「以前招生季要在不同資料夾追蹤表格、家長資料及已簽合約。現在團隊可在同一處跟進每個家庭。」",
