  "quiz.offer.testimonial.school.role3": "管理員 · 120 位學生",
  "quiz.offer.testimonial.school.copy3": "「分期付款時間表讓追款工作從容得多。聯絡家長前，我能清楚看到到期款項，毋須手動重新整理名單。」",
  "quiz.offer.testimonial.school.name4": "藝術教育學校",
  "quiz.offer.testimonial.school.role4": "財務協調員 · 9 個課程",
