  "landing.custom.badge": "最大的分別",
  "landing.custom.title": "軟件配合你的工作方式 - 而不是相反",
  "landing.custom.sub": "每間學校和每間機構的運作都稍有不同。當標準流程不合用，我們會把 Tutlio 調整到配合你的流程 - 通常只需數星期，而非數季。以下是我們已為客戶完成的一些例子：",
  "landing.custom.ex1Title": "設有電子簽署的年度合約",
  "landing.custom.ex1Desc": "一間私立學校希望家長以電子方式簽署年度合約、分期付款，並讓每筆款項出現在可直接交給會計的匯出檔案中。現在整個流程都在 Tutlio 內完成。",
  "landing.custom.ex2Title": "導師報酬與佣金規則",
  "landing.custom.ex2Desc": "一間機構按科目和課堂類型支付導師報酬，再加上公司佣金。我們把他們的規則寫進系統，導師的每月結算和發票便會自動生成。",
  "landing.custom.ex3Title": "家長一按即可接受的建議",
  "landing.custom.ex3Desc": "一間學校希望以電郵推介額外課堂，讓家長一按即可接受 - 毋須開設帳戶，也毋須列印。現在接受、收費和第一堂的邀請都會自動進行。",
  "landing.custom.ex4Title": "你的品牌，在你的網站上",
  "landing.custom.ex4Desc": "一間機構希望使用自己的標誌和色彩，並把登入介面嵌入自家網站，讓學生和家長不會覺得離開了網站。現在 Tutlio 以他們的品牌運作。",
  "landing.custom.note": "這些都不是另一個特別版本。每項調整都會成為貴團隊已在使用的同一產品的一部分，日後所有更新同樣適用。",
  "landing.custom.cta": "告訴我們你的運作方式",
  "landing.custom.soloTitle": "還欠缺甚麼嗎？",
  "landing.custom.soloNote": "我們經常為個別客戶開發功能 - 由一條付款規則到整套工作流程。告訴我們甚麼能為你節省時間。",
