  "compare.chooseThem": "以下情況適合選 {name}",
  "compare.customTitle": "我們把產品配合你 - 而不是反過來",
  "compare.customBody": "大部分補習平台可以設定，卻不能改動。Tutlio 由一支細小團隊開發和維護，會把每個客戶自己的做法（合約流程、薪酬規則、家長確認連結、你自己品牌的專頁）帶進大家共用的同一套產品。如果你的補習社或中介有一套軟件必須遷就的流程，我們會做出來。",
